// postOutput uploads size generated bytes as an output named name. After the
// first chunk of the file has been sent, midway runs, if given, before the
// rest follows.
func (l *teamLab) postOutput(t *testing.T, token, name string, size int64, midway func()) (int, map[string]any) {
	t.Helper()
	pr, pw := io.Pipe()
	mw := multipart.NewWriter(pw)
	go func() {
		err := mw.WriteField("path", name)
		var part io.Writer
		if err == nil {
			part, err = mw.CreateFormFile("file", "upload")
		}
		src := &patterned{left: size}
		if err == nil && midway != nil {
			if _, err = io.CopyN(part, src, 64<<10); err == nil {
				midway()
			}
		}
		if err == nil {
			_, err = io.Copy(part, src)
		}
		if err == nil {
			err = mw.Close()
		}
		pw.CloseWithError(err)
	}()
	req, _ := http.NewRequest("POST", l.s.URL+"/api/role/outputs", pr)
	req.Header.Set("Content-Type", mw.FormDataContentType())
	req.Header.Set("Authorization", "Bearer "+token)
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		t.Fatalf("output upload: %v", err)
	}
	defer resp.Body.Close()
	var out map[string]any
	_ = json.NewDecoder(resp.Body).Decode(&out)
	return resp.StatusCode, out
}

func (l *teamLab) outputRecords(t *testing.T) int {
	return l.s.count(t, "SELECT count(*) FROM record WHERE card_id = $1 AND kind = 'output'", l.card.ID)
}

// outputBlobs counts the files stored under the workspace's outputs.
func (l *teamLab) outputBlobs(t *testing.T) int {
	t.Helper()
	n := 0
	root := filepath.Join(l.s.H.Blobs.(storage.Local).Dir, l.ws, "outputs")
	err := filepath.WalkDir(root, func(_ string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if !d.IsDir() {
			n++
		}
		return nil
	})
	if err != nil && !errors.Is(err, fs.ErrNotExist) {
		t.Fatal(err)
	}
	return n
}

func sumOf(size int64) string {
	h := sha256.New()
	_, _ = io.Copy(h, &patterned{left: size})
	return hex.EncodeToString(h.Sum(nil))
}

func TestAnOutputIsRecordedForItsRun(t *testing.T) {
	l := newTeamLab(t, 0)
	leader := l.claim(t)
	code, out := l.postOutput(t, leader.token, "result.npz", 1<<10, nil)
	if code != 201 {
		t.Fatalf("upload %d %v", code, out)
	}
	want := sumOf(1 << 10)
	if out["key"] != "o1" || out["name"] != "result.npz" || out["size_bytes"] != float64(1<<10) || out["sha256"] != want || out["content_type"] == "" {
		t.Fatalf("answer %v", out)
	}
	var kind, key, column, role, runID, blobKey, runColumn, runRole string
	var round, runRound int
	var body []byte
	if err := l.s.Env.Owner.QueryRow(t.Context(), `SELECT r.kind, r.key, r.board_column, r.round, r.role, r.agent_run_id, r.body, r.blob_key,
		a.board_column, a.round, a.role FROM record r JOIN agent_run a ON a.id = r.agent_run_id WHERE r.card_id = $1 AND r.kind = 'output'`, l.card.ID).
		Scan(&kind, &key, &column, &round, &role, &runID, &body, &blobKey, &runColumn, &runRound, &runRole); err != nil {
		t.Fatal(err)
	}
	if kind != "output" || key != "o1" || runID != leader.id || column != runColumn || round != runRound || role != runRole || role != leader.role {
		t.Fatalf("record %s %s %s/%d/%s run %s", kind, key, column, round, role, runID)
	}
	var b map[string]any
	json.Unmarshal(body, &b)
	if b["name"] != "result.npz" || b["size_bytes"] != float64(1<<10) || b["sha256"] != want || b["content_type"] != out["content_type"] || b["at"] == nil || b["agent_run_id"] != leader.id {
		t.Fatalf("body %v", b)
	}
	if !strings.HasPrefix(blobKey, l.ws+"/outputs/") {
		t.Fatalf("blob key %q", blobKey)
	}
	rc, err := l.s.H.Blobs.Get(t.Context(), blobKey)
	if err != nil {
		t.Fatal(err)
	}
	defer rc.Close()
	got, _ := io.ReadAll(rc)
	stored := sha256.Sum256(got)
	if len(got) != 1<<10 || hex.EncodeToString(stored[:]) != want {
		t.Fatalf("blob holds %d bytes", len(got))
	}
	if n := l.s.count(t, "SELECT count(*) FROM event WHERE card_id = $1 AND type = 'blob.created' AND payload->>'blob_key' = $2", l.card.ID, blobKey); n != 1 {
		t.Fatalf("%d blob.created events", n)
	}
}

func TestOutputKeysAreSequentialUnderConcurrency(t *testing.T) {
	l := newTeamLab(t, 0)
	leader := l.claim(t)
	var mu sync.Mutex
	var keys []string
	var wg sync.WaitGroup
	for g := range 2 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range 5 {
				code, out := l.postOutput(t, leader.token, "g"+string(rune('a'+g))+"/"+string(rune('0'+i))+".csv", 100, nil)
				if code != 201 {
					t.Errorf("upload %d %v", code, out)
					return
				}
				mu.Lock()
				keys = append(keys, out["key"].(string))
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	slices.Sort(keys)
	want := []string{"o1", "o10", "o2", "o3", "o4", "o5", "o6", "o7", "o8", "o9"}
	if !slices.Equal(keys, want) {
		t.Fatalf("keys %v", keys)
	}
}

func TestAnOutputOverTheLimitsLeavesNothing(t *testing.T) {
	l := newTeamLab(t, 0)
	leader := l.claim(t)
	refused := func(t *testing.T, name string, size int64, want int) {
		t.Helper()
		recs, blobs := l.outputRecords(t), l.outputBlobs(t)
		if code, out := l.postOutput(t, leader.token, name, size, nil); code != want {
			t.Fatalf("%q: %d %v, want %d", name, code, out, want)
		}
		if n := l.outputRecords(t); n != recs {
			t.Fatalf("%d output records, had %d", n, recs)
		}
		if n := l.outputBlobs(t); n != blobs {
			t.Fatalf("%d output blobs, had %d", n, blobs)
		}
	}
	t.Run("too big", func(t *testing.T) { refused(t, "big.bin", MaxAttachmentBytes+1, 413) })
	for _, name := range []string{"../x", "/etc/x", `a\b`, strings.Repeat("a", 513), "a/../b", "", "a\x00b"} {
		t.Run("name "+name[:min(len(name), 12)], func(t *testing.T) { refused(t, name, 10, 400) })
	}
	t.Run("too many", func(t *testing.T) {
		defer func(n int32) { maxRunOutputs = n }(maxRunOutputs)
		maxRunOutputs = 2
		for i := range 2 {
			if code, out := l.postOutput(t, leader.token, "n"+string(rune('0'+i)), 10, nil); code != 201 {
				t.Fatalf("output %d: %d %v", i, code, out)
			}
		}
		refused(t, "n2", 10, 400)
	})
	t.Run("too much in all", func(t *testing.T) {
		defer func(n int64) { maxRunOutputBytes = n }(maxRunOutputBytes)
		// the two outputs of the run so far hold 20 bytes
		maxRunOutputBytes = 3000
		if code, out := l.postOutput(t, leader.token, "s1", 2000, nil); code != 201 {
			t.Fatalf("output: %d %v", code, out)
		}
		refused(t, "s2", 981, 400)
		if code, out := l.postOutput(t, leader.token, "s3", 980, nil); code != 201 {
			t.Fatalf("output to the cap: %d %v", code, out)
		}
	})
}

func TestASettledRunCannotSaveOutputs(t *testing.T) {
	l := newTeamLab(t, 0)
	leader := l.claim(t)
	l.complete(t, leader)
	if code, out := l.postOutput(t, leader.token, "late.csv", 100, nil); code != 401 {
		t.Fatalf("settled upload %d %v", code, out)
	}
	if l.outputRecords(t) != 0 || l.outputBlobs(t) != 0 {
		t.Fatal("a settled run's upload left a record or a blob")
	}
}

func TestARunSettlingMidUploadLeavesNoBlob(t *testing.T) {
	l := newTeamLab(t, 0)
	leader := l.claim(t)
	settled := 0
	code, out := l.postOutput(t, leader.token, "slow.bin", 1<<20, func() {
		settled = l.s.call(t, "POST", "/api/daemon/agent-runs/"+leader.id+"/complete", l.personal, "", leader.ref, nil)
	})
	if settled != 200 {
		t.Fatalf("complete %d", settled)
	}
	if code != 401 {
		t.Fatalf("upload %d %v", code, out)
	}
	if l.outputRecords(t) != 0 || l.outputBlobs(t) != 0 {
		t.Fatal("an upload whose run settled left a record or a blob")
	}
}

